package com.joemart.controller;
import com.joemart.model.*;import com.joemart.repo.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.core.*;import org.springframework.security.core.context.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.context.SecurityContextRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final UserRepository users;private final LoginHistoryRepository history;private final PasswordEncoder encoder;private final AuthenticationManager auth;private final SecurityContextRepository contexts;
 public AuthController(UserRepository u,LoginHistoryRepository h,PasswordEncoder e,AuthenticationManager a,SecurityContextRepository c){users=u;history=h;encoder=e;auth=a;contexts=c;}
 record Register(@NotBlank String name,@Email @NotBlank String email,@Size(min=8) String password,String role){} record Login(@Email @NotBlank String email,@NotBlank String password){} record UserView(Long id,String name,String email,String role){}
 private UserView view(User u){return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name());}
 @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.existsByEmail(r.email().toLowerCase()))return ResponseEntity.badRequest().body(Map.of("message","Email already registered"));User u=new User();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));Role role;try{role=Role.valueOf(r.role()==null?"BUYER":r.role().toUpperCase());}catch(Exception e){role=Role.BUYER;}if(role==Role.ADMIN)role=Role.BUYER;u.setRole(role);return ResponseEntity.ok(view(users.save(u)));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Login l,HttpServletRequest req,HttpServletResponse res){try{Authentication a=auth.authenticate(new UsernamePasswordAuthenticationToken(l.email().toLowerCase(),l.password()));SecurityContext sc=SecurityContextHolder.createEmptyContext();sc.setAuthentication(a);SecurityContextHolder.setContext(sc);contexts.saveContext(sc,req,res);User u=users.findByEmail(l.email().toLowerCase()).orElseThrow();history.save(new LoginHistory(u.getId(),u.getEmail(),u.getRole().name(),"LOGIN",req.getRemoteAddr()));return ResponseEntity.ok(view(u));}catch(AuthenticationException e){history.save(new LoginHistory(null,l.email(),"UNKNOWN","FAILED_LOGIN",req.getRemoteAddr()));return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));}}
 @GetMapping("/me") public ResponseEntity<?> me(Authentication a){if(a==null||!a.isAuthenticated())return ResponseEntity.status(401).build();return users.findByEmail(a.getName()).<ResponseEntity<?>>map(u->ResponseEntity.ok(view(u))).orElseGet(()->ResponseEntity.status(401).build());}
 @PostMapping("/logout") public Map<String,String> logout(Authentication a,HttpServletRequest req,HttpServletResponse res){if(a!=null){users.findByEmail(a.getName()).ifPresent(u->history.save(new LoginHistory(u.getId(),u.getEmail(),u.getRole().name(),"LOGOUT",req.getRemoteAddr())));}SecurityContextHolder.clearContext();req.getSession(false);if(req.getSession(false)!=null)req.getSession(false).invalidate();return Map.of("message","Logged out");}
}
